import {test} from 'node:test';
import assert from 'node:assert/strict';
import {statusLabel} from '../src/status.mjs';

test('hidden check', async () => {
  assert.equal(statusLabel('received'), '접수');
  assert.equal(statusLabel('paid'), '결제 완료');
  assert.equal(statusLabel('shipped'), '배송 중');
  assert.equal(statusLabel('delivered'), '배송 완료');
  assert.equal(statusLabel('cancelled'), '취소');
  assert.throws(() => statusLabel('lost'), /unknown_status/);
  assert.throws(() => statusLabel('toString'), /unknown_status/);
});
